import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"JipperOverlayer","description":"","frontmatter":{"title":"JipperOverlayer","order":6},"headers":[],"relativePath":"zh/mods/jipperoverlayer.md","filePath":"zh/mods/jipperoverlayer.md","lastUpdated":1786943111000}'),l={name:"zh/mods/jipperoverlayer.md"};function i(n,e,s,d,g,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="jipperoverlayer" tabindex="-1">JipperOverlayer <a class="header-anchor" href="#jipperoverlayer" aria-label="Permalink to &quot;JipperOverlayer&quot;">​</a></h1><blockquote><p>ADOFAI 游戏内<strong>屏幕叠加</strong> Mod：实时显示进度、准确率、BPM、连击与判定等信息。支持 <strong>Unity Mod Manager</strong> 与 <strong>MelonLoader</strong>，设置界面支持英 / 韩 / 中三语。</p><p>项目地址：<a href="https://github.com/adofaiex/JipperOverlayer" target="_blank" rel="noreferrer">https://github.com/adofaiex/JipperOverlayer</a></p></blockquote><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><strong>实时叠加</strong>：进度、准确率（Accuracy / XAccuracy）、音乐/地图时间、检查点、最佳纪录</li><li><strong>BPM 显示</strong>：地板 BPM、当前 BPM、KPS，带伪 BPM 检测</li><li><strong>连击计数</strong>：动画连击显示 + 颜色渐变</li><li><strong>判定显示</strong>：Miss / Bad / Good / Perfect 等命中细分</li><li><strong>时间缩放</strong>：当前 timing scale 百分比</li><li><strong>尝试次数追踪</strong>：每张地图的尝试次数（持久化存储）</li><li><strong>进度条</strong>：可视进度指示</li><li><strong>Jongyeol 模式</strong>：扩展叠加，含 FPS、状态、死亡次数、起始位置、时值分析、隐藏调试文本</li><li><strong>双人支持</strong>：多人各自显示</li><li><strong>文本效果</strong>：全局阴影（TMP Underlay）与描边，RGBA 颜色选择器、宽度/柔化滑块</li><li><strong>分区字体</strong>：每个叠加位独立字体与字号（Main / BPM / Judgement / Combo / Timing / Attempt）</li><li><strong>UI 补丁开关</strong>：测试版水印、关卡名位置、自动文本重排可独立开关</li><li><strong>颜色编辑器</strong>：所有叠加色的交互式渐变编辑器</li><li><strong>XPerfect 集成</strong>：可选增强完美显示（需 <a href="https://github.com/8100print/XPerfect" target="_blank" rel="noreferrer">XPerfect</a>）</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><h3 id="unity-mod-manager" tabindex="-1">Unity Mod Manager <a class="header-anchor" href="#unity-mod-manager" aria-label="Permalink to &quot;Unity Mod Manager&quot;">​</a></h3><ol><li>安装 <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UMM</a></li><li>从 <a href="https://github.com/adofaiex/JipperOverlayer/releases" target="_blank" rel="noreferrer">Releases</a> 下载 <strong>UMM</strong> 版本</li><li>通过 UMM 安装，或解压到 <code>ADOFAI/Mods/JipperOverlayer/</code></li></ol><h3 id="melonloader" tabindex="-1">MelonLoader <a class="header-anchor" href="#melonloader" aria-label="Permalink to &quot;MelonLoader&quot;">​</a></h3><ol><li>安装 <a href="https://melonwiki.xyz/" target="_blank" rel="noreferrer">MelonLoader</a></li><li>下载 <strong>MelonLoader</strong> 版本</li><li>解压到 <code>ADOFAI/Mods/JipperOverlayer-melon/</code></li><li>游戏内按 <strong>F7</strong> 打开设置（可改键）</li></ol><h2 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to &quot;要求&quot;">​</a></h2><ul><li>Steam 版 ADOFAI</li><li>UnityModManager 0.22.14+ <strong>或</strong> MelonLoader</li><li>支持游戏版本 v136 与 v141+</li></ul><h2 id="疑难解答" tabindex="-1">疑难解答 <a class="header-anchor" href="#疑难解答" aria-label="Permalink to &quot;疑难解答&quot;">​</a></h2><blockquote><p>📝 待补充（欢迎在仓库 Issues 中反馈）</p></blockquote>',13)])])}const m=r(l,[["render",i]]);export{c as __pageData,m as default};
